const config = {
  "previewFeatures": [],
  "clientVersion": "7.5.0",
  "engineVersion": "280c870be64f457428992c43c1f6d557fab6e29e",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider       = \"prisma-client-js\"\n  output         = \"../src/generated/prisma\"\n  jsModuleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n/// Invariant database (trigger, unique): lihat `server/prisma/DB-INVARIANTS.md`.\n\n/// =========================\n/// MODUL 1 — MASTER & AKSES\n/// =========================\nmodel Pengguna {\n  penggunaId                      String               @id @default(uuid())\n  email                           String               @unique\n  opdId                           String\n  nama                            String\n  kataSandi                       String\n  peran                           PeranPengguna\n  nip                             String               @unique\n  jabatan                         String\n  pangkat                         String\n  nohp                            String\n  sesiTokenVersion                Int                  @default(0)\n  refreshTokenHash                String?              @db.VarChar(255)\n  refreshTokenExpiresAt           DateTime?\n  passwordChangedAt               DateTime?\n  ttePinHash                      String?              @db.VarChar(255)\n  deletedAt                       DateTime?\n  createdAt                       DateTime             @default(now())\n  updatedAt                       DateTime             @updatedAt\n  detailSopDibuat                 DetailSOP[]          @relation(\"SOPDibuatOleh\")\n  detailSopDiedit                 DetailSOP[]          @relation(\"SOPDieditOleh\")\n  logEditSop                      LogEditSOP[]\n  logNilaiEvaluasi                LogNilaiEvaluasi[]\n  nilaiEvaluasiDiisi              NilaiEvaluasi[]      @relation(\"NilaiDiisiOleh\")\n  nilaiEvaluasiDitindaklanjuti    NilaiEvaluasi[]      @relation(\"NilaiDitindaklanjutiOleh\")\n  pengajuanEvaluasiDiselesaikan   PengajuanEvaluasi[]  @relation(\"PengajuanDiselesaikanOleh\")\n  pengajuanEvaluasiDitandatangani PengajuanEvaluasi[]  @relation(\"PengajuanDitandatanganiOlehPjPenyusun\")\n  pengajuanEvaluasiDiverifikasi   PengajuanEvaluasi[]  @relation(\"PengajuanDiverifikasiOleh\")\n  peraturanTerakhirDiedit         Peraturan[]          @relation(\"PeraturanTerakhirDiedit\")\n  opd                             OPD                  @relation(fields: [opdId], references: [opdId], onDelete: Restrict)\n  riwayatOpd                      RiwayatOpdPengguna[]\n  tandaTangan                     RiwayatTandaTangan[]\n\n  @@index([opdId, peran, deletedAt], map: \"Pengguna_opdId_peran_deletedAt_idx\")\n}\n\nmodel OPD {\n  opdId              String               @id @default(uuid())\n  nama               String\n  deletedAt          DateTime?\n  createdAt          DateTime             @default(now())\n  updatedAt          DateTime             @updatedAt\n  pelaksana          Pelaksana[]\n  pengajuanEvaluasi  PengajuanEvaluasi[]\n  pengguna           Pengguna[]\n  riwayatOpdPengguna RiwayatOpdPengguna[]\n  opdPeraturan       OPDPeraturan[]\n  sop                SOP[]\n\n  @@index([deletedAt, nama], map: \"OPD_deletedAt_nama_idx\")\n}\n\nmodel RiwayatOpdPengguna {\n  penggunaId String\n  opdId      String\n  isAktif    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  opd        OPD      @relation(fields: [opdId], references: [opdId], onDelete: Restrict)\n  pengguna   Pengguna @relation(fields: [penggunaId], references: [penggunaId], onDelete: Cascade)\n\n  @@id([penggunaId, opdId])\n  @@index([opdId, isAktif], map: \"RiwayatOpdPengguna_opdId_isAktif_idx\")\n}\n\n/// =========================\n/// MODUL 1 — MASTER & AKSES (REGULASI)\n/// =========================\nmodel Peraturan {\n  peraturanId    String         @id @default(uuid())\n  nama           String\n  nomor          String\n  tahun          Int\n  tentang        String\n  lastEditedById String?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n  dasarHukum     DasarHukum[]\n  opdPemakai     OPDPeraturan[]\n  lastEditedBy   Pengguna?      @relation(\"PeraturanTerakhirDiedit\", fields: [lastEditedById], references: [penggunaId], onDelete: SetNull)\n\n  @@unique([nomor, tahun])\n  @@index([lastEditedById])\n}\n\nmodel OPDPeraturan {\n  opdId       String\n  peraturanId String\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  opd         OPD       @relation(fields: [opdId], references: [opdId], onDelete: Cascade)\n  peraturan   Peraturan @relation(fields: [peraturanId], references: [peraturanId], onDelete: Cascade)\n\n  @@id([opdId, peraturanId])\n}\n\n/// =========================\n/// MODUL 2 — AUTHORING SOP (INTI)\n/// =========================\nmodel SOP {\n  sopId      String      @id @default(uuid())\n  opdId      String\n  judul      String\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n  detailSops DetailSOP[]\n  opd        OPD         @relation(fields: [opdId], references: [opdId])\n\n  @@index([opdId])\n}\n\nmodel DetailSOP {\n  detailSopId String @id @default(uuid())\n  sopId       String\n\n  status                         StatusSOP                        @default(DRAFT)\n  versi                          Int                              @default(1)\n  nomorSOP                       String                           @unique\n  tanggalPembuatan               DateTime                         @default(now())\n  tanggalRevisi                  DateTime?\n  /// Diisi otomatis saat status menjadi BERLAKU via TTE Kepala OPD (tanggal kalender pengesahan, WIB).\n  tanggalEfektif                 DateTime?\n  namaLembaga                    String                           @db.Text\n  dibuatOlehId                   String?\n  terakhirDieditOlehId           String?\n  /// Versi sumber saat dibuat dari SOP BERLAKU (revisi resmi).\n  revisiDariDetailSopId          String?\n  createdAt                      DateTime                         @default(now())\n  updatedAt                      DateTime                         @updatedAt\n  revisiDari                     DetailSOP?                       @relation(\"RevisiDariVersiBerlaku\", fields: [revisiDariDetailSopId], references: [detailSopId], onDelete: Restrict)\n  revisiMenjadi                  DetailSOP[]                      @relation(\"RevisiDariVersiBerlaku\")\n  dasarHukum                     DasarHukum[]\n  dibuatOleh                     Pengguna?                        @relation(\"SOPDibuatOleh\", fields: [dibuatOlehId], references: [penggunaId], onDelete: Restrict)\n  sop                            SOP                              @relation(fields: [sopId], references: [sopId], onDelete: Cascade)\n  terakhirDieditOleh             Pengguna?                        @relation(\"SOPDieditOleh\", fields: [terakhirDieditOlehId], references: [penggunaId], onDelete: Restrict)\n  swimlanes                      DetailSOPPelaksana[]\n  lampiranPeringatan             LampiranPeringatan[]\n  lampiranKualifikasiPelaksanaan LampiranKualifikasiPelaksanaan[]\n  lampiranPeralatanPerlengkapan  LampiranPeralatanPerlengkapan[]\n  lampiranPencatatanPendataan    LampiranPencatatanPendataan[]\n  langkahSOP                     LangkahSOP[]\n  logEditSop                     LogEditSOP[]\n  nilaiEvaluasi                  NilaiEvaluasi[]\n  relasiSopKeluar                SopTerkait[]                     @relation(\"RelasiSOP\")\n  relasiSopMasuk                 SopTerkait[]                     @relation(\"RelasiSOPTerkait\")\n  dokumenTte                     DokumenTte[]\n  konfigurasiDiagram             KonfigurasiDiagramSOP[]\n\n  @@unique([sopId, versi])\n  @@index([sopId, status])\n  @@index([sopId, status, versi], map: \"DetailSOP_sopId_status_versi_idx\")\n  @@index([status, updatedAt])\n  @@index([status, tanggalEfektif], map: \"DetailSOP_status_tanggalEfektif_idx\")\n  @@index([revisiDariDetailSopId])\n}\n\n/// Daftar teks lampiran peringatan per versi DetailSOP (replace-all saat simpan; bukan riwayat append-only).\nmodel LampiranPeringatan {\n  lampiranPeringatanId String    @id @default(uuid())\n  detailSopId          String\n  teks                 String    @db.Text\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n  detailSop            DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@index([detailSopId])\n}\n\n/// Daftar teks kualifikasi pelaksanaan per versi DetailSOP (replace-all saat simpan).\nmodel LampiranKualifikasiPelaksanaan {\n  lampiranKualifikasiPelaksanaanId String    @id @default(uuid())\n  detailSopId                      String\n  teks                             String    @db.Text\n  createdAt                        DateTime  @default(now())\n  updatedAt                        DateTime  @updatedAt\n  detailSop                        DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@index([detailSopId])\n}\n\n/// Daftar teks peralatan/perlengkapan per versi DetailSOP (replace-all saat simpan).\nmodel LampiranPeralatanPerlengkapan {\n  lampiranPeralatanPerlengkapanId String    @id @default(uuid())\n  detailSopId                     String\n  teks                            String    @db.Text\n  createdAt                       DateTime  @default(now())\n  updatedAt                       DateTime  @updatedAt\n  detailSop                       DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@index([detailSopId])\n}\n\n/// Daftar teks pencatatan/pendataan per versi DetailSOP (replace-all saat simpan).\nmodel LampiranPencatatanPendataan {\n  lampiranPencatatanPendataanId String    @id @default(uuid())\n  detailSopId                   String\n  teks                          String    @db.Text\n  createdAt                     DateTime  @default(now())\n  updatedAt                     DateTime  @updatedAt\n  detailSop                     DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@index([detailSopId])\n}\n\nmodel DasarHukum {\n  detailSopId String\n  peraturanId String\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  peraturan   Peraturan @relation(fields: [peraturanId], references: [peraturanId])\n  detailSop   DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@id([detailSopId, peraturanId])\n  @@index([peraturanId], map: \"DasarHukum_peraturanId_idx\")\n}\n\n/// Relasi keluar: `detailSopId` (pemilik) → `detailSopTerkaitId` (target). Invariant DB + app:\n/// tidak boleh self-loop. Pasangan terbalik `(B,A)` boleh karena keterkaitan SOP bersifat simetris di UI.\nmodel SopTerkait {\n  detailSopId        String\n  detailSopTerkaitId String\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n  sop                DetailSOP @relation(\"RelasiSOP\", fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n  sopTerkait         DetailSOP @relation(\"RelasiSOPTerkait\", fields: [detailSopTerkaitId], references: [detailSopId], onDelete: Cascade)\n\n  @@id([detailSopId, detailSopTerkaitId])\n  @@index([detailSopTerkaitId], map: \"SopTerkait_detailSopTerkaitId_idx\")\n}\n\n/// `pelaksanaId` harus dari OPD yang sama dengan SOP pemilik `detailSopId` (trigger DB + validasi prosedur).\nmodel LangkahSOP {\n  langkahSopId               String                    @id @default(uuid())\n  detailSopId                String\n  kegiatan                   String                    @db.Text\n  jenis                      JenisLangkahProsedur      @default(KEGIATAN)\n  urutan                     Int\n  kelengkapan                String\n  keluaran                   String\n  waktu                      Int\n  satuanWaktu                SatuanWaktu\n  keterangan                 String                    @db.Text\n  pelaksanaId                String\n  langkahSelanjutnyaYaId     String?\n  langkahSelanjutnyaTidakId  String?\n  createdAt                  DateTime                  @default(now())\n  updatedAt                  DateTime                  @updatedAt\n  langkahTidak               LangkahSOP?               @relation(\"LangkahTidak\", fields: [langkahSelanjutnyaTidakId], references: [langkahSopId])\n  langkahSebelumTidak        LangkahSOP[]              @relation(\"LangkahTidak\")\n  langkahYa                  LangkahSOP?               @relation(\"LangkahYa\", fields: [langkahSelanjutnyaYaId], references: [langkahSopId])\n  langkahSebelumYa           LangkahSOP[]              @relation(\"LangkahYa\")\n  overridePanahSebagaiSumber OverridePanahDiagramSOP[] @relation(\"OverridePanahDariLangkah\")\n  overridePanahSebagaiTujuan OverridePanahDiagramSOP[] @relation(\"OverridePanahKeLangkah\")\n  pelaksana                  Pelaksana                 @relation(fields: [pelaksanaId], references: [pelaksanaId])\n  detailSop                  DetailSOP                 @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@unique([detailSopId, urutan])\n  @@index([pelaksanaId], map: \"LangkahSOP_pelaksanaId_idx\")\n  @@index([langkahSelanjutnyaYaId], map: \"LangkahSOP_langkahSelanjutnyaYaId_idx\")\n  @@index([langkahSelanjutnyaTidakId], map: \"LangkahSOP_langkahSelanjutnyaTidakId_idx\")\n}\n\nmodel Pelaksana {\n  pelaksanaId String               @id @default(uuid())\n  opdId       String\n  nama        String\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n  sopDetails  DetailSOPPelaksana[]\n  langkahSOP  LangkahSOP[]\n  opd         OPD                  @relation(fields: [opdId], references: [opdId])\n\n  @@index([opdId, nama], map: \"Pelaksana_opdId_nama_idx\")\n}\n\n/// Swimlane: `pelaksanaId` harus master `Pelaksana` dengan `opdId` sama seperti `SOP` pemilik `DetailSOP` (trigger DB).\nmodel DetailSOPPelaksana {\n  detailSopId String\n  pelaksanaId String\n  urutan      Int       @default(0)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  pelaksana   Pelaksana @relation(fields: [pelaksanaId], references: [pelaksanaId])\n  detailSop   DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@id([detailSopId, pelaksanaId])\n  @@index([pelaksanaId], map: \"DetailSOPPelaksana_pelaksanaId_idx\")\n}\n\n/// =========================\n/// MODUL 3 — KOLABORASI SOP (log aktivitas; tabel Komentar terpisah sudah dihapus)\n/// =========================\n\n/// Log aktivitas edit per DetailSOP (kunci alami sesi: detail + pengguna + waktu mulai).\nmodel LogEditSOP {\n  detailSopId     String\n  penggunaId      String\n  createdAt       DateTime                @default(now()) @db.DateTime(3)\n  bagian          BagianSOP               @default(HEADER)\n  /// Ringkasan human-readable yang sudah memuat label bagian + field yang berubah.\n  keterangan      String?                 @db.Text\n  /// Jumlah event yang digabung dalam sesi (bekas `meta.count`).\n  sesiChangeCount Int                     @default(1)\n  /// Sesi dianggap selesai bila tidak null. Sesi terbuka (null) bisa di-merge dengan edit lanjutan dalam idle window.\n  closedAt        DateTime?               @db.DateTime(3)\n  updatedAt       DateTime                @updatedAt @db.DateTime(3)\n  detailSop       DetailSOP               @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n  pengguna        Pengguna                @relation(fields: [penggunaId], references: [penggunaId])\n  domainFields    LogEditSopDomainField[]\n\n  @@id([detailSopId, penggunaId, createdAt])\n  @@index([detailSopId, penggunaId, bagian, closedAt])\n  @@index([detailSopId, createdAt])\n}\n\n/// Field domain yang berubah dalam satu sesi log (normalisasi bekas `meta.fields`).\nmodel LogEditSopDomainField {\n  detailSopId  String\n  penggunaId   String\n  logCreatedAt DateTime   @db.DateTime(3)\n  domainField  String     @db.VarChar(191)\n  logEditSop   LogEditSOP @relation(fields: [detailSopId, penggunaId, logCreatedAt], references: [detailSopId, penggunaId, createdAt], onDelete: Cascade)\n\n  @@id([detailSopId, penggunaId, logCreatedAt, domainField])\n}\n\n/// =========================\n/// MODUL 5 — PENGAJUAN & EVALUASI SOP\n/// ======================= ==\nmodel PengajuanEvaluasi {\n  pengajuanEvaluasiId                String                  @id @default(uuid())\n  opdId                              String\n  jenis                              JenisPengajuanEvaluasi\n  status                             StatusPengajuanEvaluasi @default(SEDANG_DIEVALUASI)\n  nomorBA                            String?\n  tanggalPermintaan                  DateTime?\n  tanggalEvaluasi                    DateTime?\n  nilaiOPD                           Int?\n  diverifikasiOlehUserId             String?\n  ditandatanganiOlehPjPenyusunUserId String?\n  tanggalTTDBaPjPenyusun             DateTime?\n  /// Evaluator yang men-trigger \"selesai evaluasi\" → kirim ke PJ Evaluator Organisasi.\n  /// Syarat: semua NilaiEvaluasi dalam pengajuan ini sudah terisi hasil.\n  diselesaikanOlehId                 String?\n  tanggalDiselesaikan                DateTime?\n  /// Versi untuk optimistic locking — increment di setiap update status.\n  /// Service: UPDATE ... SET status = ?, version = version + 1 WHERE id = ? AND version = ?\n  version                            Int                     @default(0)\n  createdAt                          DateTime                @default(now())\n  updatedAt                          DateTime                @updatedAt\n  logNilaiEvaluasi                   LogNilaiEvaluasi[]\n  nilaiEvaluasi                      NilaiEvaluasi[]\n  diselesaikanOleh                   Pengguna?               @relation(\"PengajuanDiselesaikanOleh\", fields: [diselesaikanOlehId], references: [penggunaId])\n  ditandatanganiOlehPjPenyusunUser   Pengguna?               @relation(\"PengajuanDitandatanganiOlehPjPenyusun\", fields: [ditandatanganiOlehPjPenyusunUserId], references: [penggunaId], onDelete: Restrict)\n  diverifikasiOlehUser               Pengguna?               @relation(\"PengajuanDiverifikasiOleh\", fields: [diverifikasiOlehUserId], references: [penggunaId], onDelete: Restrict)\n  dokumenTte                         DokumenTte[]\n  opd                                OPD                     @relation(fields: [opdId], references: [opdId])\n\n  @@index([opdId, status, createdAt])\n  @@index([opdId, status, updatedAt], map: \"PengajuanEvaluasi_opdId_status_updatedAt_idx\")\n  @@index([opdId, status, tanggalDiselesaikan, updatedAt], map: \"PengajuanEvaluasi_opd_status_selesai_idx\")\n  @@index([status, createdAt], map: \"PengajuanEvaluasi_status_createdAt_idx\")\n}\n\n/// Hasil penilaian per DetailSOP dalam satu pengajuan evaluasi.\n/// Umpan balik evaluasi resmi = catatan + statusTindakLanjut pada baris ini (bukan tabel Komentar).\nmodel NilaiEvaluasi {\n  pengajuanEvaluasiId   String\n  detailSopId           String\n  hasil                 HasilEvaluasi?\n  /// Catatan formal evaluator; wajib jika hasil PERLU_PERBAIKAN.\n  catatan               String?             @db.Text\n  /// Status tindak lanjut umpan balik: TERBUKA (belum) | SELESAI (sudah ditandai penyusun).\n  statusTindakLanjut    StatusTindakLanjut?\n  ditindaklanjutiPada   DateTime?\n  ditindaklanjutiOlehId String?\n  version               Int                 @default(0)\n  dinilaiOlehId         String?\n  createdAt             DateTime            @default(now())\n  updatedAt             DateTime            @updatedAt\n  dinilaiOleh           Pengguna?           @relation(\"NilaiDiisiOleh\", fields: [dinilaiOlehId], references: [penggunaId])\n  ditindaklanjutiOleh   Pengguna?           @relation(\"NilaiDitindaklanjutiOleh\", fields: [ditindaklanjutiOlehId], references: [penggunaId])\n  pengajuanEvaluasi     PengajuanEvaluasi   @relation(fields: [pengajuanEvaluasiId], references: [pengajuanEvaluasiId])\n  detailSop             DetailSOP           @relation(fields: [detailSopId], references: [detailSopId])\n  logNilaiEvaluasi      LogNilaiEvaluasi[]\n\n  @@id([pengajuanEvaluasiId, detailSopId])\n  @@index([pengajuanEvaluasiId])\n  @@index([pengajuanEvaluasiId, hasil], map: \"NilaiEvaluasi_pengajuanEvaluasiId_hasil_idx\")\n  @@index([detailSopId])\n}\n\nmodel LogNilaiEvaluasi {\n  pengajuanEvaluasiId String\n  detailSopId         String\n  penggunaId          String\n  hasilSebelum        HasilEvaluasi?\n  hasilSesudah        HasilEvaluasi?\n  catatanSebelum      String?           @db.Text\n  catatanSesudah      String?           @db.Text\n  createdAt           DateTime          @default(now()) @db.DateTime(3)\n  pengguna            Pengguna          @relation(fields: [penggunaId], references: [penggunaId])\n  pengajuanEvaluasi   PengajuanEvaluasi @relation(fields: [pengajuanEvaluasiId], references: [pengajuanEvaluasiId])\n  nilaiEvaluasi       NilaiEvaluasi     @relation(fields: [pengajuanEvaluasiId, detailSopId], references: [pengajuanEvaluasiId, detailSopId], onDelete: Cascade)\n\n  @@id([pengajuanEvaluasiId, detailSopId, penggunaId, createdAt])\n  @@index([detailSopId, createdAt])\n}\n\n/// =========================\n/// MODUL 6 — LEGALISASI & TTE\n/// =========================\n/// Wajib tepat satu parent: `detailSopId` XOR `pengajuanEvaluasiId` (CHECK MySQL, lihat migrasi invariant).\n\nmodel DokumenTte {\n  dokumenTteId        String               @id @default(uuid())\n  nomorDokumen        String               @unique\n  jenisDokumen        JenisDokumenTte\n  judulDokumen        String\n  hashDokumen         String\n  versiDokumen        Int                  @default(1)\n  detailSopId         String?\n  pengajuanEvaluasiId String?\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n  detailSop           DetailSOP?           @relation(fields: [detailSopId], references: [detailSopId], onDelete: Restrict)\n  pengajuanEvaluasi   PengajuanEvaluasi?   @relation(fields: [pengajuanEvaluasiId], references: [pengajuanEvaluasiId], onDelete: Restrict)\n  riwayatTandaTangan  RiwayatTandaTangan[]\n\n  @@unique([detailSopId])\n  @@unique([pengajuanEvaluasiId])\n  @@index([jenisDokumen, createdAt], map: \"DokumenTte_jenisDokumen_createdAt_idx\")\n}\n\nmodel RiwayatTandaTangan {\n  userId             String\n  dokumenTteId       String\n  peran              PeranPengguna\n  signatureValue     String?       @db.LongText\n  signatureAlgorithm String?\n  signatureFormat    String?\n  certSerialNumber   String?\n  certIssuer         String?\n  certSubject        String?\n  certFingerprint    String?\n  certValidFrom      DateTime?\n  certValidTo        DateTime?\n  ditandatanganiPada DateTime      @default(now())\n  dokumenTte         DokumenTte    @relation(fields: [dokumenTteId], references: [dokumenTteId], onDelete: Restrict)\n  user               Pengguna      @relation(fields: [userId], references: [penggunaId])\n\n  @@id([userId, dokumenTteId])\n  @@unique([dokumenTteId, peran])\n}\n\n/// =========================\n/// ENUMS\n/// =========================\nenum PeranPengguna {\n  PJ_EVALUATOR\n  EVALUATOR\n  KEPALA_OPD\n  PJ_PENYUSUN\n  PENYUSUN\n}\n\nenum StatusSOP {\n  DRAFT\n  SEDANG_DISUSUN\n  SIAP_DIEVALUASI\n  DIAJUKAN_EVALUASI\n  SEDANG_DIEVALUASI\n  REVISI_DARI_EVALUATOR\n  SIAP_DIVERIFIKASI\n  DIVERIFIKASI_PJ_EVALUATOR_ORGANISASI\n  BERLAKU\n  DIGANTIKAN\n  DICABUT\n}\n\nenum JenisLangkahProsedur {\n  AWAL_AKHIR\n  KEGIATAN\n  KEPUTUSAN\n}\n\nenum SatuanWaktu {\n  m\n  h\n  d\n  w\n  mo\n  y\n}\n\nenum JenisPengajuanEvaluasi {\n  TERJADWAL\n  MANDIRI\n}\n\nenum StatusPengajuanEvaluasi {\n  SEDANG_DIEVALUASI\n  SELESAI_DIEVALUASI\n  DIVERIFIKASI_PJ_EVALUATOR\n  DITANDATANGANI_PJ_PENYUSUN\n  SELESAI\n}\n\nenum HasilEvaluasi {\n  SESUAI\n  PERLU_PERBAIKAN\n}\n\nenum JenisDokumenTte {\n  BERITA_ACARA_EVALUASI\n  SOP_BERLAKU\n}\n\n/// Status penyelesaian umpan balik evaluasi pada `NilaiEvaluasi.statusTindakLanjut`.\nenum StatusTindakLanjut {\n  TERBUKA\n  SELESAI\n}\n\n/// Kategori bagian SOP pada log aktivitas edit (`LogEditSOP.bagian`).\nenum BagianSOP {\n  HEADER\n  LANGKAH\n  STATUS\n  UMPAN_BALIK\n  EVALUASI\n}\n\n/// Jenis diagram SOP (flowchart cetak / BPMN pratinjau).\nenum JenisDiagram {\n  FLOWCHART\n  BPMN\n}\n\nenum CabangDiagram {\n  UTAMA\n  YA\n  TIDAK\n}\n\nenum SisiPanahDiagram {\n  top\n  bottom\n  left\n  right\n}\n\n/// Agregat konfigurasi diagram per DetailSOP (bukan junction M:N). Layout node otomatis di klien.\nmodel KonfigurasiDiagramSOP {\n  detailSopId   String\n  jenis         JenisDiagram\n  layoutSeed    Int                       @default(0)\n  updatedAt     DateTime                  @updatedAt\n  overridePanah OverridePanahDiagramSOP[]\n  overrideLabel OverrideLabelDiagramSOP[]\n\n  detailSop DetailSOP @relation(fields: [detailSopId], references: [detailSopId], onDelete: Cascade)\n\n  @@id([detailSopId, jenis])\n  @@index([detailSopId])\n}\n\n/// Override koordinat panah manual (anak `KonfigurasiDiagramSOP`).\nmodel OverridePanahDiagramSOP {\n  detailSopId      String\n  jenis            JenisDiagram\n  dariLangkahSopId String\n  keLangkahSopId   String\n  cabang           CabangDiagram\n  sSide            SisiPanahDiagram\n  eSide            SisiPanahDiagram\n  startX           Float\n  startY           Float\n  endX             Float\n  endY             Float\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  konfigurasiDiagram KonfigurasiDiagramSOP       @relation(fields: [detailSopId, jenis], references: [detailSopId, jenis], onDelete: Cascade)\n  dariLangkah        LangkahSOP                  @relation(\"OverridePanahDariLangkah\", fields: [dariLangkahSopId], references: [langkahSopId], onDelete: Cascade)\n  keLangkah          LangkahSOP                  @relation(\"OverridePanahKeLangkah\", fields: [keLangkahSopId], references: [langkahSopId], onDelete: Cascade)\n  titikTekuk         TitikTekukPanahDiagramSOP[]\n\n  @@id([detailSopId, jenis, dariLangkahSopId, keLangkahSopId, cabang])\n  @@index([dariLangkahSopId])\n  @@index([keLangkahSopId])\n}\n\n/// Titik tekuk panah berurutan (anak `OverridePanahDiagramSOP`).\nmodel TitikTekukPanahDiagramSOP {\n  detailSopId      String\n  jenis            JenisDiagram\n  dariLangkahSopId String\n  keLangkahSopId   String\n  cabang           CabangDiagram\n  urutan           Int\n  x                Float\n  y                Float\n\n  overridePanah OverridePanahDiagramSOP @relation(fields: [detailSopId, jenis, dariLangkahSopId, keLangkahSopId, cabang], references: [detailSopId, jenis, dariLangkahSopId, keLangkahSopId, cabang], onDelete: Cascade)\n\n  @@id([detailSopId, jenis, dariLangkahSopId, keLangkahSopId, cabang, urutan])\n}\n\n/// Posisi label diagram manual (anak `KonfigurasiDiagramSOP`).\nmodel OverrideLabelDiagramSOP {\n  detailSopId String\n  jenis       JenisDiagram\n  kunciLabel  String\n  posisiX     Float\n  posisiY     Float\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  konfigurasiDiagram KonfigurasiDiagramSOP @relation(fields: [detailSopId, jenis], references: [detailSopId, jenis], onDelete: Cascade)\n\n  @@id([detailSopId, jenis, kunciLabel])\n}\n"
}

